export default "/*\n * outbound.css — domain residue for com.ikenga.outbound.\n *\n * Kit classes (.frame*, .ip-*, .dense-row*, .badge, .chip, .tag, .btn*,\n * .nav-group*, .nav-item*, .atelier-state.*, .ob-actions*, .cmdk) come from\n * @ikenga/tokens app-kit and are NEVER redefined here. Only these domain-local\n * classes belong in this file:\n *\n *   .nl-*            Newsletter/inner-tab layout anatomy\n *   .ob-header       Channel header block\n *   .ob-chip.*       Channel identity + status chips (provider-identity hues)\n *   .ob-filter-chip  Sent-view filter chips (workspace-tinted)\n *   .ob-seq-*        Sequences sub-state anatomy\n *   .cal-pill.*      Calendar schedule pill states\n *   Provider hues are FIXED constants (not workspace-tint tokens).\n *\n * Inject order (app.js): tokens-css → app-kit-css → outbound-css.\n * This file is regenerated by `scripts/build.mjs` from this source file.\n */\n\n/* ─── Channel header ────────────────────────────────────────────────────────── */\n\n.ob-header {\n  padding: 1rem 1.25rem 0.5rem;\n  border-bottom: 1px solid var(--border-faint);\n  flex-shrink: 0;\n}\n\n.ob-header h1 {\n  font: var(--text-h3, 600 16px/1.3 var(--font-sans, system-ui));\n  color: var(--fg);\n  margin: 0 0 0.125rem;\n}\n\n.ob-header .sub {\n  font-size: 0.75rem;\n  color: var(--fg-muted);\n  margin: 0;\n}\n\n.ob-header .meta {\n  font-size: 0.7rem;\n  color: var(--fg-faint, var(--fg-muted));\n  margin-top: 0.125rem;\n}\n\n/* ─── Inner-tab strip (.nl-inner-tabs = .pane-inner-tabs canonical) ─────────── */\n\n.nl-inner-tabs {\n  display: flex;\n  gap: 0;\n  padding: 0 0.75rem;\n  border-bottom: 1px solid var(--border-faint);\n  background: var(--bg-base);\n  flex-shrink: 0;\n}\n\n.nl-inner-tabs button {\n  background: none;\n  border: none;\n  border-bottom: 2px solid transparent;\n  cursor: pointer;\n  color: var(--fg-muted);\n  font: 0.75rem/1.4 var(--font-sans, system-ui);\n  font-weight: 500;\n  padding: 0.5rem 0.625rem;\n  margin-bottom: -1px;\n  transition: color 0.15s, border-color 0.15s;\n}\n\n.nl-inner-tabs button.is-on {\n  color: var(--tint-outbox-fg, var(--tint-fg-active, var(--fg)));\n  border-bottom-color: var(--tint-outbox-fg, var(--tint-fg-active, var(--fg)));\n}\n\n.nl-inner-tabs button:hover:not(.is-on) {\n  color: var(--fg);\n}\n\n.nl-tab-count {\n  display: inline-flex;\n  align-items: center;\n  justify-content: center;\n  min-width: 1.1rem;\n  height: 1.1rem;\n  padding: 0 0.25rem;\n  border-radius: 0.55rem;\n  background: var(--tint-outbox-bg, var(--bg-alt));\n  color: var(--tint-outbox-fg, var(--fg-muted));\n  font-size: 0.65rem;\n  font-weight: 600;\n  margin-left: 0.25rem;\n  vertical-align: middle;\n}\n\n/* ─── Queue master/detail split (.nl-split) ─────────────────────────────────── */\n\n.nl-split {\n  display: grid;\n  grid-template-columns: 320px 1fr;\n  height: 100%;\n  overflow: hidden;\n}\n\n.nl-master {\n  overflow-y: auto;\n  border-right: 1px solid var(--border-faint);\n  padding: 0.5rem 0;\n}\n\n.nl-master-group-head {\n  padding: 0.5rem 1rem 0.25rem;\n  font-size: 0.7rem;\n  font-weight: 600;\n  color: var(--fg-muted);\n  text-transform: uppercase;\n  letter-spacing: 0.04em;\n  position: sticky;\n  top: 0;\n  background: var(--bg-base);\n  z-index: 1;\n}\n\n.nl-detail {\n  overflow-y: auto;\n  padding: 0;\n  display: flex;\n  flex-direction: column;\n}\n\n/* Queue draft rows */\n.nl-row {\n  display: flex;\n  flex-direction: column;\n  gap: 0.2rem;\n  padding: 0.625rem 1rem;\n  cursor: pointer;\n  border-bottom: 1px solid var(--border-faint);\n  transition: background 0.1s;\n}\n\n.nl-row:hover {\n  background: var(--bg-alt);\n}\n\n.nl-row.is-on {\n  background: var(--bg-alt);\n  border-left: 2px solid var(--tint-outbox-fg, var(--tint-fg-active, var(--fg)));\n}\n\n.nl-row-head {\n  display: flex;\n  align-items: center;\n  gap: 0.375rem;\n  flex-wrap: wrap;\n}\n\n.nl-row-subj {\n  font-size: 0.8125rem;\n  font-weight: 500;\n  color: var(--fg);\n  white-space: nowrap;\n  overflow: hidden;\n  text-overflow: ellipsis;\n}\n\n.nl-row-pre {\n  font-size: 0.75rem;\n  color: var(--fg-muted);\n  white-space: nowrap;\n  overflow: hidden;\n  text-overflow: ellipsis;\n}\n\n/* ─── Channel identity chips (provider-identity hues — FIXED constants) ──────── */\n/* These are intentionally NOT workspace-tint tokens — provider brand colors are\n   permanent across all themes (Resend verdigris, Listmonk amber, SMTP slate-blue,\n   Buffer purple). Same rule as mail/dist/outbound.css chip palette. */\n\n.ob-chip {\n  display: inline-flex;\n  align-items: center;\n  gap: 0.2rem;\n  padding: 0.15rem 0.45rem;\n  border-radius: 0.25rem;\n  font-size: 0.65rem;\n  font-weight: 600;\n  letter-spacing: 0.02em;\n  white-space: nowrap;\n}\n\n/* Channel identity */\n.ob-chip.channel-resend {\n  background: hsl(174 60% 18%);\n  color: hsl(174 60% 72%);\n}\n\n.ob-chip.channel-listmonk {\n  background: hsl(38 80% 18%);\n  color: hsl(38 80% 72%);\n}\n\n.ob-chip.channel-smtp {\n  background: hsl(220 40% 22%);\n  color: hsl(220 40% 76%);\n}\n\n.ob-chip.channel-buffer {\n  background: hsl(265 50% 22%);\n  color: hsl(265 50% 76%);\n}\n\n/* Status */\n.ob-chip.seq {\n  background: var(--bg-alt);\n  color: var(--fg-muted);\n}\n\n.ob-chip.edited {\n  background: var(--bg-alt);\n  color: var(--fg-muted);\n  font-style: italic;\n}\n\n.ob-chip.sender {\n  background: var(--bg-alt);\n  color: var(--fg-muted);\n}\n\n/* Cold sender — reputational-risk signal */\n.ob-chip.sender.cold {\n  background: hsl(38 80% 18%);\n  color: var(--achievement, hsl(38 80% 62%));\n  font-weight: 700;\n}\n\n/* Cooling period */\n.ob-chip.cooling {\n  background: hsl(38 80% 18%);\n  color: var(--achievement, hsl(38 80% 62%));\n}\n\n/* Quality score */\n.ob-chip.quality {\n  background: var(--bg-alt);\n  color: var(--fg);\n  font-variant-numeric: tabular-nums;\n}\n\n.ob-chip.quality.high {\n  background: hsl(142 50% 18%);\n  color: hsl(142 50% 65%);\n}\n\n/* A/B variant indicator */\n.ob-chip.ab {\n  background: var(--bg-alt);\n  color: var(--fg-muted);\n  border: 1px solid var(--border-faint);\n}\n\n/* Overdue status — uses --danger */\n.ob-chip.overdue {\n  background: color-mix(in srgb, var(--danger) 15%, transparent);\n  color: var(--danger);\n  font-weight: 700;\n}\n\n/* ─── Sent-view filter chips (.ob-filter-chip) ──────────────────────────────── */\n\n.ob-filter-chip {\n  display: inline-flex;\n  align-items: center;\n  gap: 0.25rem;\n  padding: 0.2rem 0.55rem;\n  border-radius: 1rem;\n  font-size: 0.7rem;\n  font-weight: 500;\n  cursor: pointer;\n  border: 1px solid var(--border-faint);\n  background: none;\n  color: var(--fg-muted);\n  transition: background 0.1s, color 0.1s;\n}\n\n.ob-filter-chip:hover {\n  background: var(--bg-alt);\n  color: var(--fg);\n}\n\n.ob-filter-chip.is-on {\n  background: var(--tint-outbox-bg, var(--bg-alt));\n  color: var(--tint-outbox-fg, var(--fg));\n  border-color: var(--tint-outbox-fg, var(--tint-fg-active, var(--border-faint)));\n}\n\n/* ─── Calendar grid (.nl-cal-wrap / .nl-cal-week / etc.) ───────────────────── */\n\n.nl-cal-wrap {\n  padding: 0.75rem 1rem;\n  overflow-y: auto;\n  flex: 1;\n}\n\n.nl-cal-week {\n  display: grid;\n  grid-template-columns: repeat(7, 1fr);\n  gap: 0.5rem;\n  min-width: 640px;\n}\n\n.nl-cal-cell {\n  min-height: 5rem;\n  border: 1px solid var(--border-faint);\n  border-radius: 0.375rem;\n  padding: 0.375rem;\n  display: flex;\n  flex-direction: column;\n  gap: 0.25rem;\n}\n\n.nl-cal-day-num {\n  font-size: 0.7rem;\n  font-weight: 600;\n  color: var(--fg-muted);\n  margin-bottom: 0.125rem;\n}\n\n.nl-cal-day-num.today {\n  color: var(--tint-outbox-fg, var(--tint-fg-active, var(--fg)));\n}\n\n/* Calendar pills (.nl-cal-pill = .cal-pill from design) */\n.nl-cal-pill {\n  display: block;\n  padding: 0.2rem 0.4rem;\n  border-radius: 0.25rem;\n  font-size: 0.65rem;\n  font-weight: 500;\n  background: color-mix(in srgb, var(--tint-outbox-bg, var(--bg-alt)) 40%, transparent);\n  color: var(--fg);\n  white-space: nowrap;\n  overflow: hidden;\n  text-overflow: ellipsis;\n  cursor: pointer;\n}\n\n.nl-cal-pill:hover {\n  background: var(--tint-outbox-bg, var(--bg-alt));\n}\n\n/* Cooling: amber bg */\n.nl-cal-pill.cool {\n  background: hsl(38 80% 18%);\n  color: var(--achievement, hsl(38 80% 62%));\n}\n\n/* Investor update type: live green */\n.nl-cal-pill.investor {\n  background: color-mix(in srgb, var(--live, hsl(142 50% 40%)) 20%, transparent);\n  color: var(--live, hsl(142 50% 50%));\n}\n\n/* Sent (past): dim, dashed */\n.nl-cal-pill.sent {\n  background: var(--bg-base);\n  border: 1px dashed var(--border-faint);\n  opacity: 0.7;\n}\n\n/* ─── Sent view (.nl-sent-toolbar / .nl-sent-table) ─────────────────────────── */\n\n.nl-sent-toolbar {\n  display: flex;\n  align-items: center;\n  gap: 0.5rem;\n  padding: 0.625rem 1rem;\n  border-bottom: 1px solid var(--border-faint);\n  background: var(--bg-base);\n  flex-shrink: 0;\n  flex-wrap: wrap;\n}\n\n.nl-view-toggle {\n  display: flex;\n  border: 1px solid var(--border-faint);\n  border-radius: 0.375rem;\n  overflow: hidden;\n  margin-left: auto;\n}\n\n.nl-view-toggle button {\n  background: none;\n  border: none;\n  padding: 0.25rem 0.625rem;\n  font-size: 0.7rem;\n  font-weight: 500;\n  color: var(--fg-muted);\n  cursor: pointer;\n  transition: background 0.1s, color 0.1s;\n}\n\n.nl-view-toggle button.is-on {\n  background: var(--bg-alt);\n  color: var(--fg);\n}\n\n.nl-sent-body {\n  flex: 1;\n  overflow-y: auto;\n  padding: 0.75rem 1rem;\n}\n\n.nl-sent-table {\n  width: 100%;\n  border-collapse: collapse;\n  font-size: 0.75rem;\n}\n\n.nl-sent-table th {\n  text-align: left;\n  padding: 0.375rem 0.5rem;\n  border-bottom: 1px solid var(--border-faint);\n  color: var(--fg-muted);\n  font-weight: 600;\n  font-size: 0.7rem;\n  text-transform: uppercase;\n  letter-spacing: 0.03em;\n  white-space: nowrap;\n}\n\n.nl-sent-table td {\n  padding: 0.5rem 0.5rem;\n  border-bottom: 1px solid var(--border-faint);\n  color: var(--fg);\n  vertical-align: middle;\n}\n\n.nl-sent-table td.num {\n  font-variant-numeric: tabular-nums;\n  text-align: right;\n  color: var(--fg);\n}\n\n.nl-sent-table td.pct {\n  font-variant-numeric: tabular-nums;\n  text-align: right;\n  color: var(--fg-muted);\n}\n\n.nl-sent-table td.meta {\n  color: var(--fg-muted);\n  font-size: 0.7rem;\n}\n\n/* ─── Newsletter detail / quality panel ───────────────────────────────────────── */\n\n.nl-quality-wrap {\n  padding: 0.75rem 1rem;\n  border-bottom: 1px solid var(--border-faint);\n}\n\n.nl-quality-row {\n  display: flex;\n  align-items: center;\n  justify-content: space-between;\n  padding: 0.3rem 0;\n  font-size: 0.75rem;\n  color: var(--fg-muted);\n  border-bottom: 1px solid var(--border-faint);\n}\n\n.nl-quality-row:last-child {\n  border-bottom: none;\n}\n\n.nl-quality-row .label {\n  color: var(--fg-muted);\n}\n\n.nl-quality-row .score {\n  font-weight: 600;\n  color: var(--fg);\n  font-variant-numeric: tabular-nums;\n}\n\n.nl-quality-row .score.pass {\n  color: hsl(142 50% 50%);\n}\n\n.nl-quality-row .score.fail {\n  color: var(--danger);\n}\n\n/* ─── Sequences sub-state (.ob-seq-*) ────────────────────────────────────────── */\n\n.ob-seq-list {\n  display: flex;\n  flex-direction: column;\n  gap: 0;\n  overflow-y: auto;\n  flex: 1;\n}\n\n.ob-seq-row {\n  display: grid;\n  grid-template-columns: 1fr auto;\n  align-items: start;\n  gap: 0.5rem;\n  padding: 0.75rem 1rem;\n  border-bottom: 1px solid var(--border-faint);\n  cursor: pointer;\n  transition: background 0.1s;\n}\n\n.ob-seq-row:hover {\n  background: var(--bg-alt);\n}\n\n.ob-seq-row.is-on {\n  background: var(--bg-alt);\n  border-left: 2px solid var(--tint-outbox-fg, var(--tint-fg-active, var(--fg)));\n}\n\n.ob-seq-name {\n  font-size: 0.8125rem;\n  font-weight: 500;\n  color: var(--fg);\n  white-space: nowrap;\n  overflow: hidden;\n  text-overflow: ellipsis;\n}\n\n.ob-seq-meta {\n  font-size: 0.7rem;\n  color: var(--fg-muted);\n  margin-top: 0.125rem;\n}\n\n.ob-seq-stats {\n  display: flex;\n  flex-direction: column;\n  align-items: flex-end;\n  gap: 0.125rem;\n}\n\n.ob-seq-step {\n  font-size: 0.7rem;\n  color: var(--fg-muted);\n  font-variant-numeric: tabular-nums;\n}\n\n.ob-seq-detail {\n  display: flex;\n  flex-direction: column;\n  overflow-y: auto;\n  padding: 1rem;\n}\n\n/* ─── Pane-level state wrappers (.atelier-state.*) ───────────────────────────── */\n/* Classes from app-kit — only sizing overrides here if needed */\n\n.atelier-state {\n  flex: 1;\n  display: flex;\n  flex-direction: column;\n  align-items: center;\n  justify-content: center;\n  gap: 0.75rem;\n  padding: 2rem;\n  text-align: center;\n  min-height: 180px;\n}\n\n/* ─── Outbound send detail pane (approve-gate shape) ─────────────────────────── */\n/* Reuses .ip-head / .ip-meta-row / .ip-body from app-kit; only the container\n   query target is domain-local. */\n\n.ob-detail-wrap {\n  container-type: inline-size;\n  container-name: ob-detail;\n  display: flex;\n  flex-direction: column;\n  height: 100%;\n}\n\n/* ─── Cooling-period send block ───────────────────────────────────────────────── */\n\n.ob-cooling-block {\n  display: flex;\n  align-items: center;\n  gap: 0.5rem;\n  padding: 0.5rem 0.75rem;\n  background: hsl(38 80% 18%);\n  border-radius: 0.375rem;\n  font-size: 0.75rem;\n  color: var(--achievement, hsl(38 80% 62%));\n  margin: 0.5rem 0;\n}\n\n.ob-cooling-block .timer {\n  font-variant-numeric: tabular-nums;\n  font-weight: 600;\n}\n\n/* ─── A/B variant selector ────────────────────────────────────────────────────── */\n\n.ob-ab-selector {\n  display: flex;\n  gap: 0.5rem;\n  padding: 0.5rem 0;\n}\n\n.ob-ab-btn {\n  flex: 1;\n  display: flex;\n  flex-direction: column;\n  gap: 0.2rem;\n  padding: 0.5rem 0.75rem;\n  border: 1px solid var(--border-faint);\n  border-radius: 0.375rem;\n  background: none;\n  cursor: pointer;\n  text-align: left;\n  transition: border-color 0.1s, background 0.1s;\n}\n\n.ob-ab-btn.is-on {\n  border-color: var(--tint-outbox-fg, var(--tint-fg-active, var(--fg)));\n  background: var(--tint-outbox-bg, var(--bg-alt));\n}\n\n.ob-ab-label {\n  font-size: 0.7rem;\n  font-weight: 700;\n  color: var(--fg-muted);\n  text-transform: uppercase;\n  letter-spacing: 0.05em;\n}\n\n.ob-ab-subject {\n  font-size: 0.775rem;\n  font-weight: 500;\n  color: var(--fg);\n}\n\n/* ─── Social platform badge ───────────────────────────────────────────────────── */\n\n.ob-platform-badge {\n  display: inline-flex;\n  align-items: center;\n  gap: 0.25rem;\n  padding: 0.15rem 0.45rem;\n  border-radius: 0.25rem;\n  font-size: 0.65rem;\n  font-weight: 600;\n  white-space: nowrap;\n}\n\n.ob-platform-badge.linkedin {\n  background: hsl(210 80% 20%);\n  color: hsl(210 80% 72%);\n}\n\n.ob-platform-badge.twitter,\n.ob-platform-badge.x {\n  background: hsl(0 0% 15%);\n  color: hsl(0 0% 80%);\n}\n\n.ob-platform-badge.instagram {\n  background: hsl(320 60% 20%);\n  color: hsl(320 60% 72%);\n}\n\n/* ─── Responsive: nl-split collapses below 720px ────────────────────────────── */\n\n@media (max-width: 720px) {\n  .nl-split {\n    grid-template-columns: 1fr;\n  }\n\n  .nl-master {\n    display: none;\n  }\n\n  .nl-split.show-master .nl-master {\n    display: block;\n  }\n\n  .nl-split.show-master .nl-detail {\n    display: none;\n  }\n}\n\n/* ─── Reduced motion ─────────────────────────────────────────────────────────── */\n\n@media (prefers-reduced-motion: reduce) {\n  .nl-inner-tabs button,\n  .nl-row,\n  .ob-filter-chip,\n  .nl-cal-pill,\n  .ob-seq-row,\n  .ob-ab-btn {\n    transition: none;\n  }\n}\n"
